/* Debt Free — service worker.
 * Offline-first app shell. No tracking, no analytics, no network beacons.
 *
 * The precache block below is generated by `node tools/stamp-sw.mjs`;
 * VERSION is a content hash, so every deploy that changes a file ships a
 * new worker, and CI fails if the block is stale.
 */

// <precache>
const VERSION = '2.1.0-40c7129dda';
const PRECACHE = [
  '/',
  '/index.html',
  '/manifest.json',
  '/favicon.ico',
  '/assets/app.css',
  '/assets/js/app.js',
  '/assets/js/boot.js',
  '/assets/js/chart.js',
  '/assets/js/engine.js',
  '/assets/js/i18n.js',
  '/assets/js/icons.js',
  '/assets/js/money.js',
  '/assets/js/share.js',
  '/assets/js/store.js',
  '/assets/js/ui.js',
  '/assets/js/vault.js',
  '/assets/fonts/plex-arabic-arabic-400.woff2',
  '/assets/fonts/plex-arabic-arabic-600.woff2',
  '/assets/fonts/plex-arabic-arabic-700.woff2',
  '/assets/fonts/plex-arabic-latin-400.woff2',
  '/assets/fonts/plex-arabic-latin-600.woff2',
  '/assets/fonts/plex-arabic-latin-700.woff2',
  '/assets/img/icon.svg',
  '/assets/img/icon-192.png',
  '/assets/img/icon-512.png',
  '/assets/img/icon-maskable-512.png',
  '/assets/img/apple-touch-icon.png',
  '/assets/guide.css',
  '/guides/debt-buyout.html',
  '/guides/flat-vs-reducing-rate.html',
  '/guides/index.html',
  '/guides/snowball-vs-avalanche.html',
];
// </precache>

const CACHE = `debt-free-shell-${VERSION}`;

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await cache.addAll(PRECACHE.map(url => new Request(url, { cache: 'reload' })));
    // Pages from v1 (cache "debt-free-v1/v2") have no update prompt: take over directly.
    const keys = await caches.keys();
    if (keys.some(k => /^debt-free-v\d+$/.test(k))) await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(k => k.startsWith('debt-free') && k !== CACHE).map(k => caches.delete(k)));
    await self.clients.claim();
  })());
});

// The page shows "new version available"; the user's tap sends this.
self.addEventListener('message', event => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // the app makes no cross-origin requests

  // Navigations: pages from this version's cache, so HTML and assets always match.
  // The app shell answers for "/" (any query) and, offline, for unknown pages.
  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      const path = url.pathname === '/' ? '/index.html' : url.pathname.endsWith('/') ? `${url.pathname}index.html` : url.pathname;
      const hit = await cache.match(path);
      if (hit) return hit;
      try {
        return await fetch(req);
      } catch {
        return (await cache.match('/index.html')) || Response.error();
      }
    })());
    return;
  }

  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    const res = await fetch(req);
    if (res.ok && res.type === 'basic') cache.put(req, res.clone());
    return res;
  })());
});
